import re


def parse_duration(text: str) -> int:
    text = text.strip()
    if not text:
        raise ValueError("Duration string cannot be empty")

    match = re.fullmatch(r'(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?', text)
    if not match:
        raise ValueError(f"Invalid duration string: {text!r}")

    d, h, m, s = match.groups()
    if d is None and h is None and m is None and s is None:
        raise ValueError(f"Invalid duration string: {text!r}")

    return (
        int(d or 0) * 86400
        + int(h or 0) * 3600
        + int(m or 0) * 60
        + int(s or 0)
    )

