import re

def parse_duration(text: str) -> int:
    text = text.strip()
    if not text:
        raise ValueError("Empty duration string")

    match = re.fullmatch(r'(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?', text)
    if not match:
        raise ValueError(f"Invalid duration string: {text!r}")

    d, h, m, s = match.groups()
    if d is None and h is None and m is None and s is None:
        raise ValueError(f"Invalid duration string: {text!r}")

    total = 0
    if d is not None:
        total += int(d) * 86400
    if h is not None:
        total += int(h) * 3600
    if m is not None:
        total += int(m) * 60
    if s is not None:
        total += int(s)
    return total

def chunk(items: list, size: int) -> list[list]:
    if size <= 0:
        raise ValueError("size must be a positive integer")
    return [items[i : i + size] for i in range(0, len(items), size)]

